import heapq


def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_value = None

        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if ids & blocked or not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            feasible = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    feasible = False
                    break
            if not feasible:
                continue

            selected = tuple(sorted(ids))
            value = sum(job["value"] for job in subset)
            if (best is None or value > best_value or
                    (value == best_value and
                     (selected > best if tie == "largest" else selected < best))):
                best, best_value = selected, value

        if best is None:
            return {"error": "impossible"}
        return {"selected": list(best), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        order = sorted(names, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        domains = {}

        for name in names:
            allowed = []
            for row in packages[name]:
                version = row["version"]
                if version in blocked.get(name, []):
                    continue
                if name in pins and pins[name] != version:
                    continue
                allowed.append(row)
            domains[name] = allowed

        best_vector = None
        best_versions = None
        assigned = {}

        def active_deps(row):
            return [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep.get("feature") in features]

        def check():
            edges = {}
            for name, row in assigned.items():
                edges[name] = []
                for dep in active_deps(row):
                    other = dep["name"]
                    if other not in assigned:
                        return False
                    version = assigned[other]["version"]
                    if not dep["min"] <= version <= dep["max"]:
                        return False
                    edges[name].append(other)

            reached = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reached:
                    continue
                if name not in assigned:
                    return False
                reached.add(name)
                stack.extend(edges[name])
            if reached != set(assigned):
                return False

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            return all(visit(name) for name in assigned)

        def search(index):
            nonlocal best_vector, best_versions
            if index == len(names):
                if any(name not in assigned or
                       not bounds[0] <= assigned[name]["version"] <= bounds[1]
                       for name, bounds in roots.items()):
                    return
                if not check():
                    return
                vector = tuple(assigned[name]["version"] if name in assigned else -1
                               for name in order)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best_versions = {name: assigned[name]["version"]
                                     for name in names if name in assigned}
                return

            name = names[index]
            # Absence is an option unless roots or a dependency require the package;
            # final closure validation decides whether it is appropriate.
            if name not in roots:
                search(index + 1)
            bounds = roots.get(name)
            for row in domains[name]:
                if bounds is not None and not bounds[0] <= row["version"] <= bounds[1]:
                    continue
                assigned[name] = row
                search(index + 1)
                del assigned[name]

        search(0)
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = data["start"]
        initial = (data["source"], initial_mask, data["coupons"])
        distances = {initial: start}
        queue = [(start, data["source"], initial_mask, data["coupons"])]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                v = edge["v"]
                next_mask = mask | bit_for.get(v, 0)
                durations = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    durations.append((duration, remaining - 1))
                for duration, coupons_left in durations:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (v, next_mask, coupons_left)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, v, next_mask, coupons_left))
        return {"arrival": None}
    return solve


